using F = StrataLint.Scribe.FormulaDsl;
using static StrataLint.Scribe.FormulaDsl;
using static StrataLint.Scribe.DefinitionDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Arith.FibonacciAtomic.Observer;
internal sealed class NativeEffectiveSourceProducerDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Arith/FibonacciAtomic/Observer/NativeEffectiveSourceProducer.";
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "A single partial-recursive original selector acquires every finite source on its unchanged original register and returns a lossless numeric syntax name.",
        H("Effective Original Source Acquisition"), Blocks(
            Entry("sourceName", "Ordered syntax names", "The alpha leaf has name zero and the beta leaf has name one. A binary source with child names m and n has name Nat.pair(m,n)+2. Names describe the labelled ordered syntax tree, rather than any evaluation of that tree. Injectivity follows by separating leaf names from branch names and using the inverse of Nat.pair recursively.", DescribeRole.Definition),
            Entry("sourceDecoder", "Semantic recovery of the entire source", "The decoder returns the unique finite Source with the supplied name when one exists, and none otherwise. This inverse is defined by classical choice. Its exact inverse law on returned names is proved, but no effective Source-valued decoder is asserted or used by the selector.", DescribeRole.Definition),
            Entry("NumericControl", "Numeric acquired workspace", "Visit stores an address and a stack of pending right addresses or already acquired left-child names. Deliver stores an acquired name and the same stack. The standard primitive-codable sums, products and lists encode this workspace as a natural number. nameControl is a proof-side correspondence from the existing source producer's control; it is never an unknown-source argument to the program.", DescribeRole.Definition),
            Entry("initialWorkspace", "One common initialization", "The workspace is the encoding of Visit at the empty root address with an empty stack. It is fixed independently of the original source, common input and retained acquired history.", DescribeRole.Definition),
            Entry("numericTick", "One numeric producer instruction", "A visit yields an OriginalAction read at its literal address, with four encoded continuations. Alpha and beta construct their numeric leaf names; branch schedules the left address and saves the right address. An absent reply uses the alpha continuation, although source traversal never requires it. Deliver with a pending address switches to that address and saves the acquired name; deliver with a saved left name combines the two numeric names. Deliver with an empty stack stops. Invalid workspace encodings use the fixed initial control. This instruction function is computable and receives only a natural-number workspace.", DescribeRole.Definition),
            Entry("selectWorkspace", "Certified first return", "PFun.fix advances numericTick through its local continuation instructions until the next read or stop. The primitive-recursive sum, list, pairing and encoding operations give a computable numericTick, and Partrec.fix supplies the actual partial-recursive first-return certificate. A numeric local instruction corresponds to one genuine sourceControl local instruction under nameControl; first-return equality forwards selection across that instruction. There is no truth oracle and no uniform finite local-step bound.", DescribeRole.Definition),
            Entry("sourceService", "The fixed original effective service", "The OriginalEffectiveService Nat selector applies selectWorkspace to the accessible workspace projection of OriginalState. The same selector is used for every original source. Common input, epoch and acquired history are retained by the original transition semantics, while this selector ignores them. The effective field is a proved Partrec certificate, not an assumption about a boundary oracle.", DescribeRole.Definition),
            Entry("OriginalTransition", "Actual original transitions", "A read transition requires membership of the selected OriginalAction, obtains the reply from readout of the actual current register, and appends its epoch, address and numeric reply code to the retained acquired history. An update transition would advance epoch and substitute the register. For sourceService no update action belongs to any selector value, including away from reached states, so every reachable original transition preserves common input, epoch and register.", DescribeRole.Definition),
            Entry("externalTrace", "Ordered external acquisition", "The external trace maps the existing acquisitionTrace to epoch-zero read events in precisely its original order. It contains neither producer local-step markers nor evaluator local-step markers. The producer's full productionTrace remains available separately, with both genuine local actions at every branch.", DescribeRole.Definition),
            Entry("FullSourceAcquisition", "The complete sourcewise contract", "For output o, original U, common input i and retained acquired history H, this proposition requires the Partrec selector certificate, an actual OriginalRun from initialState(i,H) on U with externalTrace(U) and output o, and sourceDecoder(o)=some U. It also requires a reached stopping original state whose input is i, epoch is zero and acquired history is exactly H followed by acquisitionTrace(U) encoded as actual read events. Every reached original state preserves i, epoch zero and register U. Separately, the genuine native producer Run returns U with its full productionTrace, appends that full trace to any prior native log, and provides a finite source-free Replay for every prefix of the acquired reply word, with the exact trace prefix and terminal-boundary criterion. The native paid-read list equals the epoch-zero-tagged acquisitionTrace; its addresses are exactly nodes(U), have no duplicates, and its length is nodes(U).length. These native read events correspond one for one and in order to externalTrace(U). Every reached native producer configuration retains epoch zero and register U. Finally, for every producer control c, numericTick(workspace(c)) equals nameInstruction(sourceControl(c)): local successors have the corresponding numeric workspace, reads have all four corresponding numeric continuations, and stops have the acquired syntax name. This is an instruction correspondence, with no assertion about a chosen evaluator's microsteps. The original acquired history and the producer's full native log are distinct representations: local producer actions occur in the latter, while only acquired external events occur in the former.", DescribeRole.Definition),
            Entry("effective_source_producer", "All finite originals under one selector", "Every finite Source satisfies FullSourceAcquisition with its sourceName, for every common input and every retained initial acquired history. The proof directly uses NativeFullSourceProducer.native_source_producer for actual traversal and once-per-node acquisition. Induction on that supplied Run transports its visits, local instructions and stop to the numeric first-return selector; an enriched read execution retains the final acquired state. The original transition relation's read rule and the impossibility of any selected update establish stationary epoch and register. The existing reached_prefix_replay theorem retains the producer's complete local segments independently of the projected OriginalRun trace.", DescribeRole.Theorem),
            Paragraph(Text("This result proves sourcewise termination and certified Partrec selection with growing finite workspace and output. It supplies no uniform controller size, time, memory or read bound, physical implementation or erasure, or evaluator microstep equality with sourceControl. No explicitly chosen computational Nat.Partrec.Code with an all-state OriginalCodeRealization equation is supplied here. The existing compiler can be applied directly when such a genuine realization is provided; the selector certificate alone does not install an evaluator program."))
        )));
    private static DocumentBlock Entry(string n, string title, string prose, DescribeRole role) =>
        Describe.Lean(DescribeId.Create("native-effective-source-" + n.Replace("_", "-").ToLowerInvariant()),
            DeclarationHandle.Create(Prefix + n), H(title),
            role == DescribeRole.Theorem ? StatementSource.FromAuthor(Disp(
                All("i", V("Nat"), All("H", Call("List", V("OriginalEvent")), All("U", V("Source"),
                    Call("FullSourceAcquisition", Call("sourceName", V("U")), V("U"), V("i"), V("H")))))))
                : StatementSource.WithoutFormula(),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text(prose))), role);
    private static Formula V(string n) => F.Id(n);
    private static Formula Call(string n, params Formula[] args) =>
        new Formula.Apply(Seq(Operatorname, Grp(V(n))), [.. args]);
    private static Formula All(string n, Formula t, Formula b) =>
        Seq(Forall, Sp, V(n), Colon, Sp, t, Comma, Sp, Open, b, Close);
}
